/**
 * Golden tests: the TypeScript port must produce exactly the same numbers as the
 * original Finance OS Artifact (v9). expected.json was generated by running the same
 * scenario against the Artifact's compiled code with the clock fixed at 2026-10-19 12:00.
 */
import { describe, it, expect, beforeAll, afterAll, vi } from "vitest";
import expected from "./golden/expected.json";
import fixture from "./golden/fixture.json";
import { scenario } from "./golden/scenario";
import { buildDemoData } from "../domain/demo";
import { Finance } from "../domain/finance";
import { D } from "../domain/dates";
import { CardMath, buildInstallments } from "../domain/cards";
import { parseAmountCents, parseDateAny, parseOFX, parseCSV, csvToEntries } from "../import/parsers";
import { buildImportRows, makeCategorizer } from "../import/categorizer";
import { buildSeries } from "../domain/series";
import { validateBackup, buildBackup } from "../domain/backup";
import { normalizeSettings } from "../domain/model";
import { Money } from "../domain/money";
import { registerCategories, DEFAULT_CATEGORIES } from "../domain/categories";

let result: any;
beforeAll(() => {
  vi.useFakeTimers();
  vi.setSystemTime(new Date(2026, 9, 19, 12, 0, 0));
  registerCategories(DEFAULT_CATEGORIES);
  result = scenario({ FIXTURE: fixture, buildDemoData, Finance, D, CardMath, parseAmountCents, parseDateAny, parseOFX, parseCSV, csvToEntries,
    buildImportRows, makeCategorizer, buildSeries, buildInstallments, validateBackup, buildBackup, normalizeSettings, Money });
});
afterAll(() => { vi.useRealTimers(); });

describe("compatibilidade com o Finance OS original", () => {
  for (const key of Object.keys(expected)) {
    it(key, () => { expect(result[key]).toEqual((expected as any)[key]); });
  }
});
